    """The parsed `cadverify_spec` echo, None when the program does not print one."""
    prefix = f"{SPEC_NAME} = "
    values = list(dict.fromkeys(e.removeprefix(prefix) for e in echo if e.startswith(prefix)))
    if not values:
        return None
    if len(values) > 1:
